-- gap bool:113:31:1, written by an automated writer
test("breakit Drive.Button: pressing the key set for the big button clicks it instead of the key's usual action", function()
	local w = T.newWorld()
	local d = T.driver(w, T.ANA)
	T.settle(w)
	local bound = {}
	d.env.ClearOverrideBindings = function() bound = {} end
	d.env.SetOverrideBindingClick = function(_, prio, key) bound[key] = prio end
	T.goOnline(d, { price = 5000 })
	d.W.Drive.Button.KeepClosed(true)
	w:advance(1)
	local b = d.env.WuberDriveButton
	local function sig() return #d.chatLines * 1000 + #d:visibleTexts() end
	d:click(b)
	local s0 = sig()
	d:click(b)
	local clicked = sig() - s0
	d.W.Drive.SetKey("F5")
	s0 = sig()
	if bound.F5 then d:click(b) else d:slash("/wuber emblem") end
	eq(sig() - s0, clicked, "pressing F5 clicks the big button, as a click does")
	T.clean(w)
end)

