test("breakit Drive.Button: the floating button keeps off the chat when only the minimap has room", function()
	local w = T.newWorld()
	local d = T.driver(w, T.ANITA, { spot = "Orgrimmar" })
	T.settle(w)
	local W, env = d.W, d.env
	W.Drive.SetScale(1)
	W.Driver.SetOnline(true)
	W.UI.Toggle(true)
	w:advance(1)
	W.UI.SelectTab("Drive")
	w:advance(0.5)
	W.Driver.ShowScreen("customers")
	w:advance(2)
	local win = env.WuberFrame
	ok(win and win:IsShown(), "the phone is open")
	win:ClearAllPoints()
	win:SetPoint("CENTER", env.UIParent, "CENTER", 0, 0)
	w:advance(2)
	local k = win:GetEffectiveScale() / env.UIParent:GetEffectiveScale()
	local pr = (win:GetRight() + W.UI.PHONE.bezel) * k
	local chat = env.DEFAULT_CHAT_FRAME
	chat:ClearAllPoints()
	chat:SetPoint("TOPLEFT", env.UIParent, "TOPLEFT", math.floor(pr), 0)
	chat:SetSize(math.ceil(env.UIParent:GetWidth() - pr), env.UIParent:GetHeight())
	chat:Show()
	local mini = env.Minimap
	mini:ClearAllPoints()
	mini:SetPoint("BOTTOMLEFT", env.UIParent, "BOTTOMLEFT", 0, 0)
	mini:SetSize(env.UIParent:GetWidth(), env.UIParent:GetHeight())
	mini:Show()
	W.Drive.Button.Place()
	w:advance(2)
	local b = env.WuberDriveButton
	ok(W.Drive.Button.Floating(), "the big button floats")
	local function rect(f)
		local kk = f:GetEffectiveScale() / env.UIParent:GetEffectiveScale()
		return { l = f:GetLeft() * kk, r = f:GetRight() * kk, b = f:GetBottom() * kk, t = f:GetTop() * kk }
	end
	local r, c = rect(b), rect(chat)
	ok(not (r.l < c.r and r.r > c.l and r.b < c.t and r.t > c.b), "the floating button is not over the chat frame")
	T.clean(w)
end)

