    win:SetPoint("CENTER", env.UIParent, "CENTER", cx - env.UIParent:GetWidth() / 2, cy - env.UIParent:GetHeight() / 2)
    slot:Hide()
    B.Place()
    local nl, nr, nb, nt = rect(b)
    local wl, wr, wb, wt = rect(win)
