	local d = T.driver(w, T.ANITA, { spot = "Orgrimmar" })
	T.settle(w)
	local W, env = d.W, d.env
	T.H.state[env.UIParent].w, T.H.state[env.UIParent].h = 1365, 768
	d.physW, d.physH, d.wide = 2730, 1536, true
	d:fire("DISPLAY_SIZE_CHANGED")
	local DR = W.Drive
	DR.Button.KeepClosed(true)
	w:advance(0.5)
	env.WuberDB.drive.button.pos = { "TOPLEFT", "TOPLEFT", 200, -80 }
	DR.Button.Place()
	w:advance(0.5)
	local b = env.WuberDriveButton
	ok(b and T.H.visible(b), "drive button is visible")
	local oldLeft, oldTop = b:GetLeft(), b:GetTop()
	DR.ResetPosition()
	ok(math.abs(b:GetLeft() - oldLeft) > 20 or math.abs(b:GetTop() - oldTop) > 20, "button moves to default spot immediately")
	T.clean(w)
end)

